def transform(g0):
    h,w=len(g0),len(g0[0])
    nz=lambda i,j: 0<=i<h and 0<=j<w and g0[i][j]!=0
    C={(i,j) for i in range(h) for j in range(w) if all(nz(a,b) for a in range(i-1,i+2) for b in range(j-1,j+2))}
    res=[row[:] for row in g0]
    for mi in range(h):
        for mj in range(w):
            if g0[mi][mj] not in (0,1):
                mv=g0[mi][mj]; seen={(mi,mj)}; q=deque([(mi,mj)])
                while q:
                    i,j=q.popleft()
                    for a,b in ((i+1,j),(i-1,j),(i,j+1),(i,j-1)):
                        if 0<=a<h and 0<=b<w and g0[a][b]!=0 and (a,b) not in seen:
                            seen.add((a,b)); q.append((a,b))
                for i,j in seen:
                    if (i,j) in C and g0[i][j]==1: res[i][j]=mv
    return res
