open(d+'/lib.py','w').write('''from collections import deque

def interior_cells(grid):
    """Cells whose full 3x3 neighborhood is inside the grid and nonzero."""
    h, w = len(grid), len(grid[0])
    nz = lambda i, j: 0 <= i < h and 0 <= j < w and grid[i][j] != 0
    return {(i, j) for i in range(h) for j in range(w)
            if all(nz(a, b) for a in range(i - 1, i + 2) for b in range(j - 1, j + 2))}

def flood_from(grid, start):
    """The set of nonzero cells 4-connected to start."""
    h, w = len(grid), len(grid[0])
    seen = {start}; q = deque([start])
    while q:
        i, j = q.popleft()
        for a, b in ((i+1, j), (i-1, j), (i, j+1), (i, j-1)):
            if 0 <= a < h and 0 <= b < w and grid[a][b] != 0 and (a, b) not in seen:
                seen.add((a, b)); q.append((a, b))
    return seen

def spread_marker_color(grid):
    """Each nonzero marker cell recolors the interior cells (see interior_cells) of its 4-connected nonzero region with its own color."""
    h, w = len(grid), len(grid[0])
    C = interior_cells(grid)
    res = [row[:] for row in grid]
    for mi in range(h):
        for mj in range(w):
            if grid[mi][mj] not in (0, 1):
                mv = grid[mi][mj]
                for i, j in flood_from(grid, (mi, mj)):
                    if (i, j) in C and grid[i][j] == 1:
                        res[i][j] = mv
    return res
